True from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    output = [[bg] * w for _ in range(h)]
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        yy, xx = y + dy, x + dx
                        if (dy or dx) and 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                            seen.add((yy, xx))
                            q.append((yy, xx))
            if len(cells) >= 3:
                components.append((color, cells))

    for color, cells in components:
        top = min(r for r, c in cells); bottom = max(r for r, c in cells)
        left = min(c for r, c in cells); right = max(c for r, c in cells)
        area = (bottom - top + 1) * (right - left + 1)
        density = len(cells) / area
        occupied = sum(grid[r][c] != bg for r in range(top, bottom + 1) for c in range(left, right + 1)) / area
        for r, c in cells:
            output[r][c] = color
        rectangular = density >= 0.75 and occupied >= 0.85
        noisy_shape = len(cells) >= 7 and density >= 0.58 and occupied >= 0.70
        if rectangular or noisy_shape:
            for r in range(top, bottom + 1):
                for c in range(left, right + 1):
                    if grid[r][c] == bg:
                        continue
                    neighbors = sum(0 <= r + dr < h and 0 <= c + dc < w and grid[r + dr][c + dc] == color
                                   for dr in (-1, 0, 1) for dc in (-1, 0, 1) if dr or dc)
                    if grid[r][c] == color or rectangular or neighbors >= 2:
                        output[r][c] = color
    return output

